import React, { useRef, useState } from "react";
import api from "./api";

function CameraCapture() {
  const videoRef = useRef(null);
  const [message, setMessage] = useState("");

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }

      setMessage("📷 Camera started");
    } catch (error) {
      console.error(error);
      setMessage("❌ Camera access denied or not available");
    }
  };

  // ⚠️ Aligné avec Django: /attendance/recognize/
  const startAttendance = async () => {
    try {
      setMessage("🔍 Recognition running...");

      await api.post("/attendance/recognize/", {
        embedding: "BASE64_EMBEDDING_FROM_YOUR_PIPELINE"
      });

      setMessage("✅ Attendance recorded");
    } catch (error) {
      console.error(error);
      setMessage("❌ Recognition failed");
    }
  };

  return (
    <div>
      <h2>🎥 Attendance Detection</h2>

      <button onClick={startCamera}>Start Camera</button>

      <button onClick={startAttendance}>
        Start Attendance Detection
      </button>

      <br /><br />

      <video ref={videoRef} autoPlay playsInline width="400" />

      <p>{message}</p>
    </div>
  );
}

export default CameraCapture;
